export function urlsplit(url) {
  // strip \t \r \n everywhere; strip leading C0/space
  url = url.replace(/[\t\r\n]/g, '').replace(/^[\x00-\x20]+/, '');
  let scheme = '', netloc = '', path = '', query = '', fragment = '';
