  i = url.indexOf('?');
  if (i !== -1) { query = url.slice(i+1); url = url.slice(0, i); }
  // scheme: ':' before any '/'
  const colon = url.indexOf(':');
  if (colon > 0) {
    const cand = url.slice(0, colon);
    const slash = url.indexOf('/');
    if ((slash === -1 || colon < slash) && /^[A-Za-z][A-Za-z0-9+.-]*$/.test(cand)) {
