// Percent-encoding helpers that mirror Python's urllib.parse behavior:
//   quote()       - urllib.parse.quote       (UTF-8 bytes, uppercase hex)
//   quotePlus()   - urllib.parse.quote_plus  (space rendered as '+')
//   unquote()     - urllib.parse.unquote     (invalid escapes kept, bad
//                                            UTF-8 replaced with U+FFFD)
//   unquotePlus() - urllib.parse.unquote_plus ('+' decoded to space first)

const ALWAYS_SAFE =
  'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_.-~';

const encoder = new TextEncoder();
const decoder = new TextDecoder('utf-8', { fatal: false });

function toHex(byte) {
  return '%' + byte.toString(16).toUpperCase().padStart(2, '0');
}

export function quote(str, safe = '/') {
  const safeSet = new Set(ALWAYS_SAFE + safe);
  let out = '';
  for (const byte of encoder.encode(str)) {
    const ch = String.fromCharCode(byte);
    out += safeSet.has(ch) ? ch : toHex(byte);
  }
  return out;
}

export function quotePlus(str, safe = '') {
  const safeSet = new Set(ALWAYS_SAFE + safe);
  let out = '';
  for (const byte of encoder.encode(str)) {
    const ch = String.fromCharCode(byte);
    if (byte === 0x20) out += '+';
    else out += safeSet.has(ch) ? ch : toHex(byte);
  }
  return out;
}

const HEX_DIGIT = /[0-9A-Fa-f]/;

export function unquote(str) {
  if (!str.includes('%')) return str;
  const bytes = [];
  let literal = '';
  const flush = () => {
    if (literal !== '') {
      for (const byte of encoder.encode(literal)) bytes.push(byte);
      literal = '';
    }
  };
  let i = 0;
  while (i < str.length) {
    if (
      str[i] === '%' &&
      i + 2 < str.length + 1 &&
      HEX_DIGIT.test(str[i + 1] ?? '') &&
      HEX_DIGIT.test(str[i + 2] ?? '')
    ) {
      flush();
      bytes.push(parseInt(str.slice(i + 1, i + 3), 16));
      i += 3;
    } else {
      literal += str[i];
      i += 1;
    }
  }
  flush();
  return decoder.decode(new Uint8Array(bytes));
}

export function unquotePlus(str) {
  return unquote(str.replace(/\+/g, ' '));
}

// Path component of a URL (or of a fragment's path portion).
//
// Segments are stored percent-decoded; encoding happens at render time.
// A leading '/' maps to `isabsolute`, a trailing '/' to `isdir`; interior
// empty segments are preserved ('a//b' renders back as 'a//b').

import { quote, unquote } from './encoding.mjs';

// Characters that survive rendering unencoded inside a path segment
// (RFC 3986 sub-delims plus ':' and '@'). '?' is added by the caller
// when a fragment has no query part.
export const PATH_SEGMENT_SAFE = "!$&'()*+,;=:@";

function split(path) {
  const isabsolute = path.startsWith('/');
  const isdir = path.length > 0 && path.endsWith('/');
  const segments = path.split('/');
  if (isabsolute) segments.shift();
  if (isdir) segments.pop();
  if (path === '') segments.length = 0;
  return { segments, isabsolute, isdir };
}

export class Path {
  constructor(path = '') {
    this.segments = [];
    this.isabsolute = false;
    this.isdir = false;
    this.set(path);
  }

  set(path) {
    const parsed = split(path);
    this.segments = parsed.segments.map(unquote);
    this.isabsolute = parsed.isabsolute;
    this.isdir = parsed.isdir;
    return this;
  }

  add(path) {
    if (path === '') return this;
    const parsed = split(path);
    for (const segment of parsed.segments) this.segments.push(unquote(segment));
    this.isdir = parsed.isdir;
    return this;
  }

  render({ questionMarkSafe = false } = {}) {
    const safe = PATH_SEGMENT_SAFE + (questionMarkSafe ? '?' : '');
    let out = this.segments.map((s) => quote(s, safe)).join('/');
    if (this.isabsolute) out = '/' + out;
    if (this.isdir && this.segments.length > 0) out += '/';
    return out;
  }

  toString() {
    return this.render();
  }
}

// Query component: an ordered list of key/value pairs.
//
// Pairs written without '=' keep that distinction ('a&b=' renders back
// as 'a&b='). Keys and values are stored decoded ('+' and %XX resolved)
// and re-encoded with quote_plus semantics at render time.

import { quotePlus, unquotePlus } from './encoding.mjs';

export class Query {
  constructor(query = '') {
    this.params = [];
    this.set(query);
  }

  set(query) {
    this.params = [];
    if (query === '') return this;
    for (const item of query.split('&')) {
      const eq = item.indexOf('=');
      if (eq === -1) {
        this.params.push([unquotePlus(item), '', false]);
      } else {
        this.params.push([
          unquotePlus(item.slice(0, eq)),
          unquotePlus(item.slice(eq + 1)),
          true,
        ]);
      }
    }
    return this;
  }

  toString() {
    return this.params
      .map(([key, value, hadEquals]) =>
        hadEquals ? quotePlus(key) + '=' + quotePlus(value) : quotePlus(key)
      )
      .join('&');
  }
}

// Fragment component: a Path plus a Query.
//
// Parsing splits the fragment string on the first '?' only when the part
// after it contains '=' (observed furl behavior); otherwise the whole
// string is the path. When rendered, a raw '?' inside path segments is
// left alone while the query is empty and percent-encoded otherwise.

import { Path } from './path.mjs';
import { Query } from './query.mjs';

export class Fragment {
  constructor(fragment = '') {
    this.path = new Path();
    this.query = new Query();
    this.set(fragment);
  }

  set(fragment) {
    const q = fragment.indexOf('?');
    if (q !== -1 && fragment.slice(q + 1).includes('=')) {
      this.path.set(fragment.slice(0, q));
      this.query.set(fragment.slice(q + 1));
    } else {
      this.path.set(fragment);
      this.query.set('');
    }
    return this;
  }

  // fragment.add(path): append path segments, query untouched.
  add(path) {
    this.path.add(path);
    return this;
  }

  // fragment.set(path, args): replace both the path and the query.
  setPathArgs(path, args) {
    this.path.set(path);
    this.query.set(args);
    return this;
  }

  toString() {
    const query = this.query.toString();
    const path = this.path.render({ questionMarkSafe: query === '' });
    if (path !== '' && query !== '') return path + '?' + query;
    return query !== '' ? query : path;
